'use strict';
const DecisionPopup=(()=>{
 let displayed='',deferred='';
 const key=()=>state.calendar?.pending?state.seed+':'+state.event.id+':'+state.turn+':'+state.calendar.count:'';
 function open(){if(!state.calendar?.pending||state.dead)return;const k=key(),s=state;deferred='';displayed=k;const required=Math.max(0,...s.event.choices.map(c=>-(c.effect.gold||0)-s.gold)),withdraw=Math.round(Math.min(required,LifeSpending.summary(s).invested)*100)/100;const severe=s.event.critical?'critical':'important';modal(`<section class="decision-popup tone-${severe}" aria-labelledby="popupDecisionTitle"><div class="decision-popup-heading"><span>✦ การตัดสินใจสำคัญ</span><small>อายุ ${s.age} ปี · ${esc(KINGDOMS[s.kingdom][0])}</small></div><h2 id="popupDecisionTitle">${ctx(s.event.title)}</h2><p class="decision-popup-prose">${esc(StoryPresentation.short(WorldLore.fill(s,s.event.text,s.event.context),240))}</p><p class="decision-wallet">เงินพร้อมใช้ <b>${s.gold.toLocaleString('th-TH',{maximumFractionDigits:2})} เหรียญ</b></p>${withdraw>0?`<button id="popupWithdraw" class="secondary popup-withdraw">ถอนเงินลงทุน ${withdraw.toLocaleString('th-TH')} เหรียญมาใช้</button>`:''}<div class="choices">${s.event.choices.map((c,i)=>`<button class="choice" data-choice="${i}" ${c.effect.gold<0&&s.gold+c.effect.gold<0?'disabled':''}><span class="num">${i+1}</span><span><b>${esc(c.label)}</b><small>${esc(c.hint||'')}${c.effect.gold<0&&s.gold+c.effect.gold<0?' · เงินไม่พอ':''}</small></span><span class="arrow">→</span></button>`).join('')}</div><div class="decision-popup-progress" role="progressbar" aria-label="เวลาตัดสินใจอัตโนมัติ" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i id="popupDecisionProgress"></i></div><p id="popupDecisionStatus" class="decision-popup-status" aria-live="polite"></p><div class="decision-popup-controls"><button class="secondary" id="popupAutoToggle"></button><button class="secondary" id="deferDecision">พับเก็บไว้ก่อน</button></div></section>`,'decision');
  document.querySelectorAll('#modal [data-choice]').forEach(b=>b.onclick=()=>{if(Simulation.choose(state,Number(b.dataset.choice))){$('#modal').close();record();clock.reset();render()}});
  if($('#popupWithdraw'))$('#popupWithdraw').onclick=()=>{if(LifeSpending.transfer(state,'withdraw',withdraw)){save();clock.reset();render();open()}};$('#popupAutoToggle').onclick=()=>clock.set({auto:!clock.prefs.auto});$('#deferDecision').onclick=dismiss;paint(clock.status());
 }
 function paint(c){if(!$('#modal').open||$('#modal').dataset.mode!=='decision')return;const auto=clock.prefs.auto,button=$('#popupAutoToggle');if(!button)return;button.textContent=auto?'ปิดการตัดสินใจอัตโนมัติ':'ให้ระบบช่วยเลือก';const status=$('#popupDecisionStatus'),choice=state.event.choices[c.selected];status.textContent=auto?(c.paused?'หยุดพักอยู่ · กดเลือกได้เมื่อพร้อม':choice?'จะเลือก “'+choice.label+'” ใน '+Math.ceil(c.remaining)+' วินาที':'กำลังพิจารณาทางเลือก'):'เวลาหยุดอยู่ เลือกเมื่อพร้อม';$('#popupDecisionProgress').style.width=(auto&&c.kind==='decision'?c.progress*100:0)+'%';$('#popupDecisionProgress').parentElement.setAttribute('aria-valuenow',String(Math.round(auto?c.progress*100:0)))}
 function sync(){const d=$('#modal'),k=key();if(!k||state.dead){if(d.open&&d.dataset.mode==='decision')d.close();displayed='';deferred='';return}if(d.open){if(d.dataset.mode==='decision'&&displayed!==k)open();return}if(k!==deferred)open()}
 function dismiss(){const d=$('#modal');if(d.dataset.mode==='decision'&&state.calendar?.pending)deferred=key();d.close()}
 function closed(){const d=$('#modal');if(d.open)return;if(d.dataset.mode==='decision'){if(state.calendar?.pending)deferred=key();d.dataset.mode='general';d.classList.remove('decision-modal')}}
 function bind(){if($('#reviewDecision'))$('#reviewDecision').onclick=open}
 return {open,paint,sync,closed,dismiss,bind};
})();
